    Expr normalized = cast<num_t>(val) / Expr(65535.0f);
    init_in(j, i)  = normalized;

    // Initialize imgOut to zero.
    Func init_out("init_out");
    init_out(j, i) = cast<num_t>(0);

    // --------------------------------------------------------------------
    // Simple but effective schedule for initialization:
    //  - tile in 2D
    //  - vectorize along the innermost (fast) j dimension
    //  - parallelize across tiles in the outer i dimension
    // --------------------------------------------------------------------
    Target target = get_host_target();
    const int vec_width = target.natural_vector_size(type_of<num_t>());

    Var jo("jo"), io("io"), ji("ji"), ii("ii");

    init_in
        .tile(j, i, jo, io, ji, ii, 128, 32)
        .vectorize(ji, vec_width)
        .parallel(io);
    init_out
        .tile(j, i, jo, io, ji, ii, 128, 32)
        .vectorize(ji, vec_width)
        .parallel(io);

    // JIT once, then realize into the provided Buffers.
    init_in.compile_jit(target);
    init_out.compile_jit(target);

    init_in.realize(imgIn);
    init_out.realize(imgOut);
}

int main(int argc, char *argv[]) {
    // Problem size (Polybench constants).
    int w = W;
    int h = H;

    // Allocate arrays as Halide buffers.
    //
    // C layout: imgIn[w][h]   -> indices imgIn[i][j]
    // Halide   : Buffer(h, w) -> indices imgIn(j, i)
    Halide::Buffer<num_t, 2> imgIn(h, w);
    Halide::Buffer<num_t, 2> imgOut(h, w);
    Halide::Buffer<num_t, 2> y1(h, w);
    Halide::Buffer<num_t, 2> y2(h, w);

    // Scalar parameter.
    num_t alpha;

    // Initialize input.
    init_array(w, h, &alpha, imgIn, imgOut);

    // --------------------------------------------------------------------
    // Halide pipeline pieces for the non‑recurrent parts of the kernel
    // (the two pointwise combinations).
    // --------------------------------------------------------------------
    Var x("x"), y("y");

    // y1 and y2 will be passed into Halide as ImageParams.
    ImageParam y1_param(type_of<num_t>(), 2, "y1_param");
    ImageParam y2_param(type_of<num_t>(), 2, "y2_param");

    // First combination: imgOut = c1 * (y1 + y2)
    Func combine1("combine1");
    // Second combination: imgOut = c2 * (y1 + y2)
    Func combine2("combine2");

    num_t c1 = (num_t)1;
    num_t c2 = (num_t)1;

    combine1(x, y) = c1 * (y1_param(x, y) + y2_param(x, y));
    combine2(x, y) = c2 * (y1_param(x, y) + y2_param(x, y));

    // --------------------------------------------------------------------
    // Schedule for the pointwise combinations:
    //  - Treat x (dim 0) as the fast dimension (matches Buffer layout).
    //  - Tile x/y, vectorize in x, and parallelize across tiles in y.
    //    This gives good cache behavior and exploits all CPU cores.
    // --------------------------------------------------------------------
    Target target = get_host_target();
    const int vec_width = target.natural_vector_size(type_of<num_t>());

    Var xo("xo"), yo("yo"), xi("xi"), yi("yi");

    combine1
        .compute_root()
        .tile(x, y, xo, yo, xi, yi, 128, 32)
        .vectorize(xi, vec_width)
        .parallel(yo);
    combine2
        .compute_root()
        .tile(x, y, xo, yo, xi, yi, 128, 32)
        .vectorize(xi, vec_width)
        .parallel(yo);

    // JIT-compile the small Halide pipelines in advance so we don't
    // measure compilation time in the benchmark.
    combine1.compile_jit(target);
    combine2.compile_jit(target);

    // --------------------------------------------------------------------
    // Compute Deriche filter coefficients on the host (scalar math).
    // This mirrors the Polybench kernel_deriche coefficient setup.
    // --------------------------------------------------------------------
    num_t ea   = std::exp(-alpha);                 // exp(-alpha)
    num_t e2a  = std::exp(num_t(2.0) * alpha);     // exp(2*alpha)
    num_t e_2a = std::exp(num_t(-2.0) * alpha);    // exp(-2*alpha)

    num_t k = (num_t(1.0) - ea) * (num_t(1.0) - ea) /
              (num_t(1.0) + num_t(2.0) * alpha * ea - e2a);

    num_t a1 = k;
    num_t a5 = k;

    num_t a2 = k * ea * (alpha - num_t(1.0));
    num_t a6 = a2;

    num_t a3 = k * ea * (alpha + num_t(1.0));
    num_t a7 = a3;

    num_t a4 = -k * e_2a;
    num_t a8 = a4;

    num_t b1 = std::pow(num_t(2.0), -alpha);
    num_t b2 = -e_2a;

    // --------------------------------------------------------------------
    // Main computational kernel: Deriche filter.
    //
    // The IIR recurrences along rows and columns have true loop-carried
    // dependencies. These are not representable as legal Halide update
    // definitions (they would require reading f(x-1, ...) on the RHS),
    // so we follow the “host-driven iteration” pattern:
    //   - keep the recursive sweeps as explicit C++ loops over Buffers,
    //   - use Halide Funcs for the purely pointwise passes.
    //
    // To reduce overhead inside the tight loops, we:
    //   - cache base pointers and strides from Halide::Buffer,
    //   - iterate using raw pointers + strides instead of repeated
    //     operator() indexing.
    //
    // Buffer indexing:
    //   original C:   imgIn[i][j]
    //   Halide here:  imgIn(j, i)
    // where i in [0, w) and j in [0, h).
    // --------------------------------------------------------------------

    // Cache buffer metadata for faster inner loops.
    num_t *in_data   = imgIn.data();
    num_t *out_data  = imgOut.data();
    num_t *y1_data   = y1.data();
    num_t *y2_data   = y2.data();

    const int in_s0  = imgIn.stride(0);   // stride in j
    const int in_s1  = imgIn.stride(1);   // stride in i
    const int out_s0 = imgOut.stride(0);
    const int out_s1 = imgOut.stride(1);
    const int y1_s0  = y1.stride(0);
    const int y1_s1  = y1.stride(1);
    const int y2_s0  = y2.stride(0);
    const int y2_s1  = y2.stride(1);

    auto start = std::chrono::high_resolution_clock::now();

    // 1) Horizontal forward recursion (left -> right).
    //
    // Columns (i) are independent and each column is processed
    // downwards along j. Within a column we use contiguous
    // accesses (stride in dim 0 is 1 by construction), so this
    // pass is cache-friendly.
    for (int i = 0; i < w; ++i) {
        num_t ym1 = num_t(0);
        num_t ym2 = num_t(0);
        num_t xm1 = num_t(0);

        num_t *in_col  = in_data  + i * in_s1;
        num_t *y1_col  = y1_data  + i * y1_s1;
        num_t *in_ptr  = in_col;
        num_t *y1_ptr  = y1_col;

        for (int j = 0; j < h; ++j) {
            num_t x_ij = *in_ptr;
            num_t y_ij = a1 * x_ij + a2 * xm1 + b1 * ym1 + b2 * ym2;

            *y1_ptr = y_ij;

            xm1 = x_ij;
            ym2 = ym1;
            ym1 = y_ij;

            in_ptr += in_s0;
            y1_ptr += y1_s0;
        }
    }

    // 2) Horizontal backward recursion (right -> left).
    //
    // Again, columns are independent; we process each column upward.
    for (int i = 0; i < w; ++i) {
        num_t yp1 = num_t(0);
        num_t yp2 = num_t(0);
        num_t xp1 = num_t(0);
        num_t xp2 = num_t(0);

        num_t *in_col  = in_data  + i * in_s1;
        num_t *y2_col  = y2_data  + i * y2_s1;
        num_t *in_ptr  = in_col  + (h - 1) * in_s0;
        num_t *y2_ptr  = y2_col  + (h - 1) * y2_s0;

        for (int j = h - 1; j >= 0; --j) {
            num_t y_ij = a3 * xp1 + a4 * xp2 + b1 * yp1 + b2 * yp2;
            *y2_ptr = y_ij;

            xp2 = xp1;
            xp1 = *in_ptr;
            yp2 = yp1;
            yp1 = y_ij;

            in_ptr -= in_s0;
            y2_ptr -= y2_s0;
        }
    }

    // 3) First pointwise combination:
    //    imgOut[i][j] = c1 * (y1[i][j] + y2[i][j]);
    y1_param.set(y1);
    y2_param.set(y2);
    combine1.realize(imgOut);

    // Refresh metadata in case Halide changed strides/offsets
    // (defensive; in this pipeline the layout remains the same).
    out_data  = imgOut.data();
    out_s0    = imgOut.stride(0);
    out_s1    = imgOut.stride(1);
    y1_data   = y1.data();
    y1_s0     = y1.stride(0);
    y1_s1     = y1.stride(1);
    y2_data   = y2.data();
    y2_s0     = y2.stride(0);
    y2_s1     = y2.stride(1);

    // 4) Vertical forward recursion (top -> bottom).
    //
    // For each fixed row j, we sweep over i. This is a 1D IIR along i.
    // Accesses along i are strided in memory (stride = *_s1) due to
    // our [j, i] layout, but this matches the original C algorithm.
    for (int j = 0; j < h; ++j) {
        num_t tm1 = num_t(0);
        num_t ym1 = num_t(0);
        num_t ym2 = num_t(0);

        num_t *out_row = out_data + j * out_s0;
        num_t *y1_row  = y1_data + j * y1_s0;
        num_t *out_ptr = out_row;
        num_t *y1_ptr  = y1_row;

        for (int i = 0; i < w; ++i) {
            num_t x_ij = *out_ptr;
            num_t y_ij = a5 * x_ij + a6 * tm1 + b1 * ym1 + b2 * ym2;

            *y1_ptr = y_ij;

            tm1 = x_ij;
            ym2 = ym1;
            ym1 = y_ij;

            out_ptr += out_s1;
            y1_ptr  += y1_s1;
        }
    }

    // 5) Vertical backward recursion (bottom -> top).
    for (int j = 0; j < h; ++j) {
        num_t tp1 = num_t(0);
        num_t tp2 = num_t(0);
        num_t yp1 = num_t(0);
        num_t yp2 = num_t(0);

        num_t *out_row = out_data + j * out_s0;
        num_t *y2_row  = y2_data + j * y2_s0;
        num_t *out_ptr = out_row + (w - 1) * out_s1;
        num_t *y2_ptr  = y2_row + (w - 1) * y2_s1;

        for (int i = w - 1; i >= 0; --i) {
            num_t y_ij = a7 * tp1 + a8 * tp2 + b1 * yp1 + b2 * yp2;
            *y2_ptr = y_ij;

            tp2 = tp1;
            tp1 = *out_ptr;
            yp2 = yp1;
            yp1 = y_ij;

            out_ptr -= out_s1;
            y2_ptr  -= y2_s1;
        }
    }

    // 6) Final pointwise combination:
    //    imgOut[i][j] = c2 * (y1[i][j] + y2[i][j]);
    y1_param.set(y1);
    y2_param.set(y2);
    combine2.realize(imgOut);

    auto end      = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // --------------------------------------------------------------------
    // Output and timing, similar style to example/gemm.cpp.
    // --------------------------------------------------------------------
    using namespace std::string_literals;

    if (argc > 0 && argv[0] != ""s) {
        std::cerr << std::fixed << std::setprecision(6);
        for (int i = 0; i < w; ++i) {
            for (int j = 0; j < h; ++j) {
                // Original C prints imgOut[i][j]; here we map to imgOut(j, i).
                std::cerr << imgOut(j, i) << '\n';
            }
        }
    }

    std::cout << std::fixed << std::setprecision(6);
    std::cout << duration.count() << std::endl;

    return 0;
}
