    // and allocate Buffer(h, w).
    Var i("i"), j("j");
    Func init_in("init_in");

    Expr val = (313 * i + 991 * j) % 65536;
    // Cast the integer pattern to num_t, then normalize into [0,1].
    // Use Expr(...) for scalar literals to avoid invalid cast<T>(scalar) patterns.
    init_in(j, i) = cast<num_t>(val) / Expr((num_t)65535.0);

    // Fill imgIn.
    init_in.realize(imgIn);

