    // loop‑carried dependencies). Here we focus Halide on the purely
    // pointwise work: imgOut = c * (y1 + y2).
    // --------------------------------------------------------------------
    Var x("x"), y("y");

    // Determine a good vector width for the current host.
    Target target = get_host_target();
    const int vec_width = target.natural_vector_size(type_of<num_t>());

    // y1 and y2 will be passed into Halide as ImageParams.
    ImageParam y1_param(type_of<num_t>(), 2, "y1_param");
    ImageParam y2_param(type_of<num_t>(), 2, "y2_param");

    // Single combination Func parameterized by a scalar coefficient:
    //   imgOut = coeff * (y1 + y2)
