    //    imgOut[i][j] = c1 * (y1[i][j] + y2[i][j]);
    //
    // Bind the buffers and coefficient, then realize via the optimized
    // Halide pipeline (vectorized + parallel).
    y1_param.set(y1);
    y2_param.set(y2);
    coeff.set(c1);
    combine.realize(imgOut);

    // 4) Vertical forward recursion (top -> bottom).
    //
    // As in the original C version, this traverses columns; memory
    // access is strided in the innermost loop, but this keeps the
    // recurrence structure identical to the reference implementation.
    for (int j = 0; j < h; ++j) {
        num_t tm1 = num_t(0);
        num_t ym1 = num_t(0);
        num_t ym2 = num_t(0);

        for (int i = 0; i < w; ++i) {
