/*
 * Array initialization: replicate the Polybench init_array,
 * but using Halide::Buffer for the arrays.
 *
 * We use a small Halide pipeline here and schedule it for
 * parallel + vectorized execution, but this runs before the
 * timed region so it doesn't affect the timing result.
 */
static void init_array(int w,
                       int h,
                       num_t *alpha,
                       Halide::Buffer<num_t, 2> imgIn,
                       Halide::Buffer<num_t, 2> imgOut) {
    // Parameter of the filter.
    *alpha = static_cast<num_t>(0.25);

    // C layout: imgIn[w][h] accessed as imgIn[i][j], with j fastest.
    // Halide layout here: Buffer(h, w) accessed as imgIn(j, i),
    // so dimension 0 (j) is the fast-varying one.
    Var i("i"), j("j");
    Func init_in("init_in"), init_out("init_out");

    Expr val   = (313 * i + 991 * j) % 65536;
    Expr denom = cast<num_t>(Expr(65535.0f));

    // Note the (j, i) argument order to match Buffer(h, w).
    init_in(j, i)  = cast<num_t>(val) / denom;
    init_out(j, i) = cast<num_t>(0);

    // Simple CPU schedule: vectorize across the fast dimension (j)
    // and parallelize across the outer dimension (i).
    Target t = get_host_target();
    const int vec_width = t.natural_vector_size(type_of<num_t>());

    init_in
        .bound(j, 0, h)
        .bound(i, 0, w)
        .reorder(j, i)
        .vectorize(j, vec_width)
        .parallel(i);

    init_out
        .bound(j, 0, h)
        .bound(i, 0, w)
        .reorder(j, i)
        .vectorize(j, vec_width)
        .parallel(i);

    // Fill imgIn and imgOut.
    init_in.realize(imgIn);
    init_out.realize(imgOut);
}

int main(int argc, char *argv[]) {
    // Problem size (Polybench constants).
    const int w = W;
    const int h = H;

    // Allocate arrays as Halide buffers.
    //
    // C layout: imgIn[w][h]   -> indices imgIn[i][j]
    // Halide   : Buffer(h, w) -> indices imgIn(j, i)
    //   j in [0, h) is the fast dimension (dimension 0),
    //   i in [0, w) is the slow dimension (dimension 1).
    Halide::Buffer<num_t, 2> imgIn(h, w);
    Halide::Buffer<num_t, 2> imgOut(h, w);
    Halide::Buffer<num_t, 2> y1(h, w);
    Halide::Buffer<num_t, 2> y2(h, w);

    // Scalar parameter.
    num_t alpha;

    // Initialize input (done before timing).
    init_array(w, h, &alpha, imgIn, imgOut);

    // --------------------------------------------------------------------
    // Halide pipeline for the purely pointwise combinations:
    //   imgOut = c * (y1 + y2)
    //
    // We JIT-compile once outside the timed region and reuse it
    // twice (before and after the vertical passes).
    // --------------------------------------------------------------------
    Var x("x"), y("y");

    // y1 and y2 will be passed into Halide as ImageParams.
    ImageParam y1_param(type_of<num_t>(), 2, "y1_param");
    ImageParam y2_param(type_of<num_t>(), 2, "y2_param");
    Param<num_t> c_param("c_param");

    Func combine("combine");
    // x, y correspond directly to Buffer indices (x = j, y = i).
    combine(x, y) = c_param * (y1_param(x, y) + y2_param(x, y));

    // Schedule: row-major with x as fast dimension, y as outer.
    Target target = get_host_target();
    const int vec_width = target.natural_vector_size(type_of<num_t>());

    combine
        .bound(x, 0, h)
        .bound(y, 0, w)
        .reorder(x, y)          // x inner, y outer
        .vectorize(x, vec_width)
        .parallel(y);           // parallel across rows of i

