    // Compute Deriche filter coefficients on the host (scalar math).
    // This mirrors the Polybench kernel_deriche coefficient setup.
    // --------------------------------------------------------------------
    const num_t ea   = std::exp(-alpha);                    // exp(-alpha)
    const num_t e2a  = std::exp(static_cast<num_t>(2.0) * alpha);
    const num_t e_2a = std::exp(static_cast<num_t>(-2.0) * alpha);

    const num_t one  = static_cast<num_t>(1.0);
    const num_t two  = static_cast<num_t>(2.0);

    const num_t k = (one - ea) * (one - ea) /
                    (one + two * alpha * ea - e2a);

    const num_t a1 = k;
    const num_t a5 = k;

    const num_t a2 = k * ea * (alpha - one);
    const num_t a6 = a2;

    const num_t a3 = k * ea * (alpha + one);
    const num_t a7 = a3;

    const num_t a4 = -k * e_2a;
    const num_t a8 = a4;

    const num_t b1 = std::pow(static_cast<num_t>(2.0), -alpha);
    const num_t b2 = -e_2a;

    const num_t c1 = static_cast<num_t>(1);
    const num_t c2 = static_cast<num_t>(1);

    // --------------------------------------------------------------------
    // Helper: simple thread-based parallel_for over an integer range.
    //
    // We use this to parallelize the independent row/column recurrences.
    // Each pass keeps its loop-carried dependences within one thread,
    // but different rows/columns are processed in parallel.
    // --------------------------------------------------------------------
    auto parallel_for = [](int begin, int end, const auto &body) {
        const unsigned hw_threads = std::thread::hardware_concurrency();
        const int max_threads = static_cast<int>(hw_threads ? hw_threads : 1);
        const int n = end - begin;
        if (n <= 0 || max_threads <= 1) {
            body(begin, end);
            return;
        }

        const int n_threads = std::min(max_threads, n);
        const int chunk = (n + n_threads - 1) / n_threads;

        std::vector<std::thread> threads;
        threads.reserve(n_threads);

        for (int t = 0; t < n_threads; ++t) {
            const int s = begin + t * chunk;
            if (s >= end) break;
            const int e = std::min(s + chunk, end);
            threads.emplace_back([&body, s, e]() { body(s, e); });
        }
        for (auto &th : threads) {
            th.join();
        }
    };

    // --------------------------------------------------------------------
    // Main computational kernel: Deriche filter.
    //
    // Due to the loop-carried dependencies (IIR recurrences) along rows
    // and columns, we implement the recursive passes as explicit C++
    // loops over Halide::Buffer data, and use Halide Funcs for the
    // purely pointwise passes (the two combinations).
    //
    // Buffer indexing:
    //   original C:   imgIn[i][j]
    //   Halide here:  imgIn(j, i)
    // where i in [0, w) and j in [0, h).
    //
    // We parallelize each pass over the outer, independent dimension:
    //   - horizontal passes: parallel over i (columns),
    //   - vertical passes:   parallel over j (rows).
    // --------------------------------------------------------------------

    auto start = std::chrono::high_resolution_clock::now();

    // 1) Horizontal forward recursion (left -> right).
    //    Each column i is independent, so we parallelize over i.
    parallel_for(0, w, [&](int i_begin, int i_end) {
        for (int i = i_begin; i < i_end; ++i) {
            num_t ym1 = static_cast<num_t>(0);
            num_t ym2 = static_cast<num_t>(0);
            num_t xm1 = static_cast<num_t>(0);

            for (int j = 0; j < h; ++j) {
                const num_t x_ij = imgIn(j, i);
                const num_t y_ij = a1 * x_ij + a2 * xm1 + b1 * ym1 + b2 * ym2;
                y1(j, i) = y_ij;

                xm1 = x_ij;
                ym2 = ym1;
                ym1 = y_ij;
            }
        }
    });

    // 2) Horizontal backward recursion (right -> left).
    //    Again, each column i is independent; parallelize over i.
    parallel_for(0, w, [&](int i_begin, int i_end) {
        for (int i = i_begin; i < i_end; ++i) {
            num_t yp1 = static_cast<num_t>(0);
            num_t yp2 = static_cast<num_t>(0);
            num_t xp1 = static_cast<num_t>(0);
            num_t xp2 = static_cast<num_t>(0);

            for (int j = h - 1; j >= 0; --j) {
                const num_t y_ij = a3 * xp1 + a4 * xp2 + b1 * yp1 + b2 * yp2;
                y2(j, i) = y_ij;

                xp2 = xp1;
                xp1 = imgIn(j, i);
                yp2 = yp1;
                yp1 = y_ij;
            }
        }
    });

    // 3) First pointwise combination:
    //    imgOut[i][j] = c1 * (y1[i][j] + y2[i][j]);
    y1_param.set(y1);
    y2_param.set(y2);
    c_param.set(c1);
    combine.realize(imgOut);

    // 4) Vertical forward recursion (top -> bottom).
    //    Each row j is independent; parallelize over j.
    parallel_for(0, h, [&](int j_begin, int j_end) {
        for (int j = j_begin; j < j_end; ++j) {
            num_t tm1 = static_cast<num_t>(0);
            num_t ym1 = static_cast<num_t>(0);
            num_t ym2 = static_cast<num_t>(0);

            for (int i = 0; i < w; ++i) {
                const num_t x_ij = imgOut(j, i);
                const num_t y_ij = a5 * x_ij + a6 * tm1 + b1 * ym1 + b2 * ym2;
                y1(j, i) = y_ij;

                tm1 = x_ij;
                ym2 = ym1;
                ym1 = y_ij;
            }
        }
    });

    // 5) Vertical backward recursion (bottom -> top).
    //    Again, each row j is independent; parallelize over j.
    parallel_for(0, h, [&](int j_begin, int j_end) {
        for (int j = j_begin; j < j_end; ++j) {
            num_t tp1 = static_cast<num_t>(0);
            num_t tp2 = static_cast<num_t>(0);
            num_t yp1 = static_cast<num_t>(0);
            num_t yp2 = static_cast<num_t>(0);

            for (int i = w - 1; i >= 0; --i) {
                const num_t y_ij = a7 * tp1 + a8 * tp2 + b1 * yp1 + b2 * yp2;
                y2(j, i) = y_ij;

                tp2 = tp1;
                tp1 = imgOut(j, i);
                yp2 = yp1;
                yp1 = y_ij;
            }
        }
    });

    // 6) Final pointwise combination:
    //    imgOut[i][j] = c2 * (y1[i][j] + y2[i][j]);
    y1_param.set(y1);
    y2_param.set(y2);
    c_param.set(c2);
    combine.realize(imgOut);

    auto end      = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // --------------------------------------------------------------------
    // Output and timing, similar style to example/gemm.cpp.
    // --------------------------------------------------------------------
    using namespace std::string_literals;

    if (argc > 0 && argv[0] != ""s) {
        std::cerr << std::fixed << std::setprecision(6);
        for (int i = 0; i < w; ++i) {
            for (int j = 0; j < h; ++j) {
                // Original C prints imgOut[i][j]; here we map to imgOut(j, i).
                std::cerr << imgOut(j, i) << '\n';
            }
        }
    }

    std::cout << std::fixed << std::setprecision(6);
    std::cout << duration.count() << std::endl;

    return 0;
}
